// Zustellung (Runde 6, 10.09.2026): eine Nachricht an eine Person bringen, und
// zwar dort, wo sie mit Rupert redet. Bis dahin kannten Erinnerungen, geplante
// Aufgaben und der Heartbeat nur Telegram, mit fest verdrahteter Chat-Nummer:
// Florians Erinnerung vom 09.09. lag unter der Nummer des Betreibers.
//
// Eingabe je Item: user_id (qualifizierte Kennung: web:florian, entra:..., telegram:123),
// chat_id (Telegram-Nummer oder Sitzungskennung), text (auch message oder
// checkerMessage), session_id (optional), im_verlauf (true, wenn der Aufrufer die
// Zeile in conversations schon geschrieben hat), kopf (optionales Praefix), art.
// Wege: telegram -> der Telegram-Knoten dahinter; teams -> Bruecke /send und eine
// Zeile in conversations, damit Rupert weiss, was er geschickt hat; verlauf -> nur
// conversations (keine Teams-Zuordnung, Rupert dort nie geoeffnet, Bruecke weg).
// Wirft nie: eine gescheiterte Zustellung darf den Aufrufer nicht haengen lassen,
// die Zeile im Verlauf ist der sichere Ausgang.
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const BRIDGE_URL = '{{BRIDGE_URL}}';
const BRIDGE_SECRET = '{{BRIDGE_SECRET}}';
const pg = { apikey: SUPABASE_KEY, Authorization: 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
const MAX_TEAMS = 1900; // die Bruecke nimmt 2000 Zeichen je Nachricht

function teile(t, max) {
  const st = []; let rest = String(t);
  while (rest.length > max) {
    let cut = rest.lastIndexOf('\n\n', max);
    if (cut < max * 0.3) cut = rest.lastIndexOf('\n', max);
    if (cut < max * 0.3) cut = rest.lastIndexOf(' ', max);
    if (cut < max * 0.3) cut = max;
    st.push(rest.slice(0, cut).trimEnd()); rest = rest.slice(cut).trimStart();
  }
  if (rest) st.push(rest);
  return st;
}

const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  const userId = String(d.user_id || d.userId || '').trim();
  const chatId = String(d.chat_id || d.chatId || '').trim();
  // checkerMessage (Pruefergebnis des Heartbeat) vor message (das waere die Anweisung der Aktion).
  const roh = String(d.text || d.checkerMessage || d.message || '').trim();
  const text = (d.kopf ? String(d.kopf) : '') + roh;
  const imVerlauf = d.im_verlauf === true || d.im_verlauf === 'true';
  const r = { id: (d.id !== undefined ? d.id : null), user_id: userId, chat_id: chatId, text, weg: null, zugestellt: false, im_verlauf: imVerlauf, grund: null, session_id: null };
  if (!roh) { r.weg = 'keiner'; r.grund = 'kein Text'; out.push({ json: r }); continue; }

  // Telegram: Nummer als chat_id oder telegram:-Kennung. Sendet der Knoten dahinter.
  if (/^\d+$/.test(chatId) || /^telegram:\d+$/.test(userId)) {
    r.weg = 'telegram';
    r.chat_id = /^\d+$/.test(chatId) ? chatId : userId.replace('telegram:', '');
    out.push({ json: r }); continue;
  }

  // Teams: Entra-Kennung der Person, entweder direkt (entra:...) oder aus der Zuordnung.
  let oid = null;
  if (/^entra:/.test(userId)) oid = userId.slice(6);
  else if (userId) {
    try {
      const rows = await helpers.httpRequest({ method: 'GET',
        url: SUPABASE_URL + '/rest/v1/user_identity_map?legacy_key=eq.' + encodeURIComponent(userId) + '&select=entra_oid&limit=1',
        headers: pg, json: true, timeout: 5000 });
      if (Array.isArray(rows) && rows[0] && rows[0].entra_oid) oid = rows[0].entra_oid;
    } catch (e) { r.grund = 'Zuordnung nicht lesbar: ' + String((e && e.message) || e).slice(0, 120); }
  }
  let convId = null;
  if (oid && BRIDGE_URL) {
    try {
      for (const s of teile(text, MAX_TEAMS)) {
        const a = await helpers.httpRequest({ method: 'POST', url: BRIDGE_URL + '/send',
          headers: { 'Content-Type': 'application/json', 'X-Bridge-Secret': BRIDGE_SECRET },
          body: JSON.stringify({ aadObjectId: oid, text: s }), json: true, timeout: 20000 });
        if (!a || !a.ok) throw new Error('Bruecke: ' + JSON.stringify(a || {}).slice(0, 120));
        convId = a.conversationId || convId;
      }
      r.weg = 'teams'; r.zugestellt = true; r.grund = null;
    } catch (e) {
      const b = e && e.response && e.response.body;
      const grund = (b && (b.grund || b.error)) || String((e && e.message) || e);
      r.grund = grund === 'nicht_installiert' ? 'Rupert in Teams nie geoeffnet' : String(grund).slice(0, 160);
    }
  } else if (!r.grund) {
    r.grund = oid ? 'keine Bruecke konfiguriert' : 'keine Teams-Zuordnung fuer ' + (userId || '(leer)');
  }
  if (!r.weg) r.weg = 'verlauf';

  // Verlauf: nach Teams in die Teams-Sitzung der Person (persoenlicher Chat, teilt
  // sich seit Runde 5 den Verlauf mit dem Web), sonst in die Sitzung des Aufrufers.
  const sitzung = (r.weg === 'teams' && convId) ? ('teams:' + convId)
    : (String(d.session_id || '') || (chatId.includes(':') ? chatId : '') || userId);
  r.session_id = sitzung || null;
  if (!imVerlauf && sitzung) {
    try {
      await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/conversations',
        headers: Object.assign({ Prefer: 'return=minimal' }, pg),
        body: JSON.stringify({ session_id: sitzung, user_id: userId, role: 'assistant', content: text,
          metadata: { zustellung: r.weg, zugestellt: r.zugestellt, grund: r.grund, art: d.art || 'erinnerung' } }),
        json: false, timeout: 5000 });
      r.im_verlauf = true;
    } catch (e) { r.verlauf_fehler = String((e && e.message) || e).slice(0, 120); }
  }
  out.push({ json: r });
}
return out;
